#!/usr/bin/env python3
"""Regenerate conservative scoped source records for TASK004."""
from pathlib import Path
import json, hashlib
root=Path(__file__).resolve().parents[1]
sources=root/'sources/selberg_round2'
data=[
('PAPER-C101','The Nyman–Beurling equivalent form for the Riemann hypothesis',['Michel Balazard','Éric Saias'],'1998-11-12',1998,'Expositiones Mathematicae 18(2) (2000), 131–138; ESI 623 manuscript inspected',None,None,'https://www.esi.ac.at/preprints/esi623.pdf','ESI Preprint623; body dated12November1998, cover27October1998','balazard_saias','Introduction and §5 pp6–7, especially Question4; middle Hardy-space proof not audited.','Question4 p7 explicitly asks whether RH implies convergence for the fixed logarithmic Selberg coefficient array in the full critical-line norm. Question2 concerns arbitrary discrete arrays and Question3 unsmoothed Möbius sums.','The fixed-array question is not the discrete closure theorem. The paper predates Báez-Duarte’s solution of the arbitrary-array closure question.'),
('PAPER-C102','On the Balazard-Saias criterion for the Riemann Hypothesis',['J. Brian Conrey','Gerald Myerson'],'2000-02-09',2000,'arXiv preprint',None,'math/0002254','https://arxiv.org/abs/math/0002254v1','v1','conrey_myerson','Printed pp1–6: definitions, Proposition1, Theorem1 statement and Remarks1–2; proof of uniform convergence in remaining pages not read.','Prop1 p2 identifies the critical-line norm of ζV_N/s with the reciprocal-fractional-part norm of W_N(u)=Σ b_n{nu}/n. Theorem1 p5 states unconditional uniform convergence to −sin(2πu)/π. Remark1 pp5–6 gives the small-u contribution (Σ b_n)²/N.','Uniform convergence does not imply the weighted norm convergence at u=0. A reported Conrey–Farmer separation-conditional result is cited as in preparation rather than proved in this source.'),
('PAPER-C103','Sur un critère de Báez-Duarte pour l’hypothèse de Riemann',['Michel Balazard','Anne de Roton'],'2008-12-09',2008,'International Journal of Number Theory6(4) (2010),883–903; arXiv manuscript inspected','10.1142/S1793042110003307','0812.1689','https://arxiv.org/abs/0812.1689v1','arXiv header v1 9December2008; body prints8November2018, discrepancy recorded','balazard_roton','Printed pp1–5: main theorem, full Proposition1 proof and Proposition2–3 statements; later Soundararajan-based technical proof not audited.','Under RH, optimized d_N²≪δ(loglogN)^(5/2+δ)(logN)^(-1/2). Propositions 1–3 prove this through coefficients μ(n)n^(-ε), with ε=25(loglogN)^(5/2+δ)/sqrt(logN).','The source supplies an admissible shifted-array upper bound and hence bounds the infimum. It does not give the same bound for the fixed logarithmic Selberg family.'),
('PAPER-C104','On an analytic estimate in the theory of the Riemann zeta function and a theorem of Báez-Duarte',['Jean-François Burnol'],'2002-02-18',2002,'Acta Cientifica Venezolana54(3) (2003),210–215; arXiv preprint inspected',None,'math/0202166','https://arxiv.org/abs/math/0202166v1','v1','burnol_analytic','Printed pp1–5: Theorems 1.3–1.4, §2 proof of discrete criterion and §3 ratio estimate. Later square-integrability/causality equivalences not fully inspected.','Theorem1.3 underRH bounds ζ(s)/ζ(s+A) on Re(s)=1/2 uniformly forA≥0. Section2 uses fixedε>0 and N→∞ thenε↓0 to reconstruct discrete closure.','Two-parameter convergence does not authorize settingε=0 at finiteN or replacing shifted coefficients by a prescribed logarithmic array.'),
('PAPER-C105','A characterization of the zero-free region of the Riemann zeta function and its applications',['Fei Wei','Dongsheng Wu'],'2022-12',2022,'Expositiones Mathematicae 40(4) (2022),961–993','10.1016/j.exmath.2022.07.004',None,'https://bimsa.net/doc/publication/1424.pdf','32-page institutional manuscript createdJune2022; published preview independently checked','zero_free_2022','Institutional manuscript pp1–7 and pp27–29: Problem1, Proposition 1.9 and proof, Remark5.8, Theorem 1.10 statement. General Hardy-space characterization and all of Theorem 1.10 proof not fully audited.','Proposition 1.9 p7: fixed Selberg full-critical-line error tending to0 impliesRH and all nontrivial zeros simple. Proofpp27–28 reconstructed independently. Problem1 pp6–7 leaves RH-alone reverse open. Theorem 1.10 establishes convergence on every fixed shifted lineRe(s)>1/2 iffRH, and boundary boundedness impliesRH.','No fixed-boundary convergence underRHalone is established; a proof would also proveRH implies simplicity. Institutional and published versions differ in pagination/references, so manuscript page citations are explicit.')]
records=[]
for ident,title,authors,date,year,venue,doi,arxiv,url,version,key,scope,result,lim in data:
 b=(sources/(key+'.pdf')).read_bytes()
 r={'id':ident,'title':title,'authors':authors,'date':date,'year':year,'venue':venue,'publication_status':'published_work_preprint_inspected' if ident!='PAPER-C102' else 'preprint','doi':doi,'arxiv':arxiv,'source_url':url,'version':version,'family':['C','F'],'audit_level':0,'whole_work_read':False,'inspected_portions_level':2 if ident=='PAPER-C105' else 1,'read_scope':scope,'access_status':'full_text_accessed','available_formats':['PDF'],'source_file':str((sources/(key+'.pdf')).relative_to(root)),'source_sha256':hashlib.sha256(b).hexdigest(),'accessed_at':'2026-11-17','main_result':result,'limitations':[lim,'Only the stated scope was inspected; no whole-paper reading is claimed.'],'research_questions':['Which endpoint uniformity or arithmetic tail estimate would prove convergence for the exact prescribed Selberg family?'],'correction_search_status':'Focused later-source search performed; exhaustive forward-citation and correction history incomplete'}
 records.append(r)
 (root/'papers'/(ident+'.md')).write_text(f'# {ident} — {title}\n\n'+f'Authors: {", ".join(authors)}. {venue}. [Source]({url}). DOI: {doi or "not verified"}.\n\n'+f'Version: {version}. Accessed 2026-11-17. **Overall audit level 0; partial reading only.**\n\n'+f'Scope: {scope}\n\n'+f'{result}\n\n'+f'{lim}\n\nSee [TASK004 provenance report](../audits/selberg_provenance_round2.md) for exact norm conventions, implications and independently reconstructed proof. No source PDF is licensed for redistribution by this record.\n')
(root/'papers/selberg_round2_records.jsonl').write_text(''.join(json.dumps(r,ensure_ascii=False)+'\n' for r in records))
# Extend retrieval manifest without overwriting earlier downloads.
r=json.loads((sources/'retrieval.json').read_text())
r=[x for x in r if x.get('key')!='zero_free_2022']
r.append({'key':'zero_free_2022','url':'https://bimsa.net/doc/publication/1424.pdf','bytes':(sources/'zero_free_2022.pdf').stat().st_size,'sha256':hashlib.sha256((sources/'zero_free_2022.pdf').read_bytes()).hexdigest(),'accessed':'2026-11-17','published_identity':'https://doi.org/10.1016/j.exmath.2022.07.004'})
(sources/'retrieval.json').write_text(json.dumps(r,indent=2)+'\n')
